INSERT INTO study_posts (id, author_id, category_id, title, body, reference_url, created_at, updated_at) VALUES
                                                                                                             (1, 1, 1, 'Spring Boot 프로젝트 생성과 디렉터리 구조', 'Spring Boot 프로젝트 생성과 디렉터리 구조에 대해 수업 시간에 정리한 내용입니다.\n핵심 개념과 예제 코드를 함께 적었습니다.', NULL, '2026-10-01 09:00:00', '2026-10-01 09:00:00'),
                                                                                                             (2, 5, 2, '엔티티와 테이블 매핑 기초', '엔티티와 테이블 매핑 기초에 대해 수업 시간에 정리한 내용입니다.\n핵심 개념과 예제 코드를 함께 적었습니다.', NULL, '2026-10-02 05:00:00', '2026-10-02 05:00:00'),
                                                                                                             (3, 3, 3, 'JpaRepository가 제공하는 메서드', 'JpaRepository가 제공하는 메서드에 대해 수업 시간에 정리한 내용입니다.\n핵심 개념과 예제 코드를 함께 적었습니다.', 'https://docs.spring.io/spring-data/jpa/reference/', '2026-10-03 01:00:00', '2026-10-03 01:00:00'),
                                                                                                             (4, 4, 1, 'application.yaml 설정 정리', 'application.yaml 설정 정리에 대해 수업 시간에 정리한 내용입니다.\n핵심 개념과 예제 코드를 함께 적었습니다.', NULL, '2026-10-03 21:00:00', '2026-10-03 21:00:00'),
                                                                                                             (5, 1, 2, '@Id와 @GeneratedValue 전략 비교', '@Id와 @GeneratedValue 전략 비교에 대해 수업 시간에 정리한 내용입니다.\n핵심 개념과 예제 코드를 함께 적었습니다.', NULL, '2026-10-04 17:00:00', '2026-10-04 19:00:00'),
